create extension if not exists pgcrypto;
create table public.user_roles(user_id uuid references auth.users on delete cascade, role text not null check(role in('admin')), primary key(user_id,role));
create or replace function public.has_role(requested_role text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=requested_role); $$;
create table public.brands(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),brand_id uuid not null references public.brands on delete cascade,name text not null,slug text not null,unique(brand_id,slug));
create table public.subcategories(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories on delete cascade,name text not null,slug text not null,unique(category_id,slug));
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text default '',sku text,brand_id uuid references public.brands,categoria_id uuid references public.categories,subcategoria_id uuid references public.subcategories,active boolean not null default false,rare boolean default false,sought boolean default false,yupoo_album_url text unique,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,url text not null,storage_path text,sort_order int default 0,is_cover boolean default false);
create table public.store_settings(id int primary key default 1 check(id=1),whatsapp text not null default '5511999999999',default_message text not null default 'Olá! Tenho interesse em uma peça da Nord Imports:');
create table public.import_jobs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,status text default 'queued',phase text default 'preparando',total int default 0,created int default 0,duplicates int default 0,failures int default 0,source_url text not null,created_at timestamptz default now());
alter table public.brands enable row level security;alter table public.categories enable row level security;alter table public.subcategories enable row level security;alter table public.products enable row level security;alter table public.product_images enable row level security;alter table public.store_settings enable row level security;alter table public.import_jobs enable row level security;
create policy "public active products" on public.products for select using(active or public.has_role('admin'));create policy "public taxonomy" on public.brands for select using(true);create policy "public categories" on public.categories for select using(true);create policy "public subcategories" on public.subcategories for select using(true);create policy "public images" on public.product_images for select using(exists(select 1 from public.products p where p.id=product_id and (p.active or public.has_role('admin'))));create policy "public settings" on public.store_settings for select using(true);
create policy "admin products" on public.products for all using(public.has_role('admin')) with check(public.has_role('admin'));create policy "admin brands" on public.brands for all using(public.has_role('admin')) with check(public.has_role('admin'));create policy "admin categories" on public.categories for all using(public.has_role('admin')) with check(public.has_role('admin'));create policy "admin subcategories" on public.subcategories for all using(public.has_role('admin')) with check(public.has_role('admin'));create policy "admin images" on public.product_images for all using(public.has_role('admin')) with check(public.has_role('admin'));create policy "admin settings" on public.store_settings for all using(public.has_role('admin')) with check(public.has_role('admin'));create policy "admin imports" on public.import_jobs for all using(public.has_role('admin')) with check(public.has_role('admin'));
insert into storage.buckets(id,name,public) values('products','products',true) on conflict do nothing;create policy "product images public" on storage.objects for select using(bucket_id='products');create policy "admin product uploads" on storage.objects for all using(bucket_id='products' and public.has_role('admin')) with check(bucket_id='products' and public.has_role('admin'));
